use std::io::{self, Write};

const TABLE: [(&str, u32); 3] = [("apples", 3), ("pears", 5), ("plums", 2)];

fn write_table(mut output: impl Write, csv: bool) -> io::Result<()> {
    if csv {
        writeln!(output, "fruit,count")?;
    }
    for (name, count) in TABLE {
        if csv {
            writeln!(output, "{name},{count}")?;
        } else {
            writeln!(output, "{name:<8}{count}")?;
        }
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let csv = std::env::args().skip(1).any(|arg| arg == "--csv");
    write_table(io::stdout().lock(), csv)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn csv_output_includes_header() {
        let mut output = Vec::new();
        write_table(&mut output, true).unwrap();
        assert_eq!(output, b"fruit,count\napples,3\npears,5\nplums,2\n");
    }

    #[test]
    fn default_output_is_unchanged() {
        let mut output = Vec::new();
        write_table(&mut output, false).unwrap();
        assert_eq!(output, b"apples  3\npears   5\nplums   2\n");
    }
}
